def load() -> pd.DataFrame:
    import pandas as pd
    path = "data/legal/input/csn-data-book-2024-csv/CSVs/2024_CSN_Report_Categories.csv"
    # File appears to be encoded with Windows-1252 (curly quotes 0x93, etc.)
    return pd.read_csv(path, encoding="cp1252")

def process(reportCategories, reportCount) -> pd.DataFrame:
    import pandas as pd

    cats = reportCategories.copy()
    cnt = reportCount.copy()

    cats.columns = [str(c).strip() for c in cats.columns]

    def find_col(df, candidates):
        lower = {c.lower(): c for c in df.columns}
        for cand in candidates:
            if cand.lower() in lower:
                return lower[cand.lower()]
        return None

    yearColCats = find_col(cats, ["Year", "Report Year", "year"])
    categoryCol = find_col(cats, ["Category", "Report Category", "report_category"])
    percentCol = find_col(cats, ["Percent", "%", "Percentage", "percent", "Share"])
    countColCats = find_col(cats, ["Count", "Reports", "# of Reports", "Number of Reports", "n"])

    if yearColCats is None or categoryCol is None:
        raise ValueError(f"Could not find Year/Category columns in categories file. Columns={list(cats.columns)}")

    cats[yearColCats] = pd.to_numeric(cats[yearColCats], errors='coerce')
    cats[categoryCol] = cats[categoryCol].astype(str).str.strip()

    cats2024 = cats[cats[yearColCats] == 2024].copy()
    if cats2024.empty:
        raise ValueError("No 2024 rows found in categories file")

    autoRow = cats2024[cats2024[categoryCol].str.lower() == 'auto related']
    if autoRow.empty:
        # allow partial match
        autoRow = cats2024[cats2024[categoryCol].str.lower().str.contains('auto')]
    if autoRow.empty:
        raise ValueError("No Auto Related category row found for 2024")

    # compute auto share fraction
    autoShareFrac = None
    if percentCol is not None and autoRow[percentCol].notna().any():
        val = autoRow.iloc[0][percentCol]
        if isinstance(val, str):
            val = val.strip().replace('%', '')
        val = pd.to_numeric(val, errors='coerce')
        if pd.isna(val):
            autoShareFrac = None
        else:
            val = float(val)
            if val <= 1:
                autoShareFrac = val
            else:
                autoShareFrac = val / 100.0

    if autoShareFrac is None:
        if countColCats is None:
            raise ValueError("Cannot compute share: no usable Percent column and no Count column")
        cats2024[countColCats] = pd.to_numeric(cats2024[countColCats], errors='coerce')
        autoCnt2024 = pd.to_numeric(autoRow.iloc[0][countColCats], errors='coerce')
        total2024 = cats2024[countColCats].sum()
        autoShareFrac = float(autoCnt2024) / float(total2024)

    # 2007 total reports from cleaned reportCount
    cnt2007 = cnt[cnt['Year'] == 2007]
    if cnt2007.empty:
        raise ValueError("No 2007 row found in report count data")
    total2007 = float(cnt2007.iloc[0]['Reports'])

    hypo = int(round(total2007 * autoShareFrac))

    return pd.DataFrame([{
        'autoShareFrac2024': autoShareFrac,
        'totalReports2007': total2007,
        'hypoAutoRelated2007': hypo
    }])
